const names=['Alyssa Marvin','Patrick Wilson','Margaret Cho','Sophia Torres','Molly Ringwald','Julie Christeas'];
const wall=document.querySelector('#gallery'),dialog=document.querySelector('dialog'),status=document.querySelector('#status');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let photos=[],design='loose',album='sundance',selected=0,viewIndex=0,request=0,opener=null,slider=false;
const stageDesigns=['case','fan'];
const scrolling=()=>['strip','museum'].includes(design)||(design==='flip'&&slider);
function setSelection(index){selected=Math.max(0,Math.min(photos.length-1,index));[...wall.children].forEach((button,i)=>{button.classList.toggle('is-current',i===selected);button.classList.toggle('is-before',i===selected-1);button.classList.toggle('is-after',i===selected+1);if(design==='case'||design==='fan'){const visible=design==='case'?i===selected:Math.abs(i-selected)<=1;button.tabIndex=visible?0:-1;button.setAttribute('aria-hidden',String(!visible));}});document.querySelector('#position').textContent=`${selected+1} / ${photos.length}`;document.querySelector('#prev').disabled=selected===0;document.querySelector('#next').disabled=selected===photos.length-1;}
function updateScroll(){if(!scrolling()||!wall.children.length)return;const left=wall.getBoundingClientRect().left;let nearest=0,distance=Infinity;[...wall.children].forEach((el,i)=>{const d=Math.abs(el.getBoundingClientRect().left-left);if(d<distance){distance=d;nearest=i;}});setSelection(nearest);const atEnd=wall.scrollLeft+wall.clientWidth>=wall.scrollWidth-3;document.querySelector('#next').disabled=atEnd;document.querySelector('#prev').disabled=wall.scrollLeft<3;}
function move(amount){if(scrolling()){const target=wall.children[Math.max(0,Math.min(photos.length-1,selected+amount))];if(target)wall.scrollTo({left:wall.scrollLeft+target.getBoundingClientRect().left-wall.getBoundingClientRect().left,behavior:reduced.matches?'instant':'smooth'});}else setSelection(selected+amount);}
function render(){wall.replaceChildren();wall.hidden=album!=='sundance';selected=0;status.hidden=album==='sundance';document.querySelector('.layout-tools').hidden=design!=='flip'||album!=='sundance';document.querySelector('.browse').hidden=album!=='sundance'||!(stageDesigns.includes(design)||scrolling());document.querySelectorAll('[data-album]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.album===album)));wall.setAttribute('aria-label',album==='sundance'?'Sundance 2026 photographs':'Behind the scenes photographs');if(album!=='sundance')return;photos.forEach((photo,i)=>{const button=document.createElement('button');button.className='photo';button.setAttribute('aria-label',`Open ${photo.name} photograph`);const image=document.createElement('img');image.src=photo.src;image.alt=photo.name+' at Sundance 2026';image.decoding='async';image.loading='eager';const name=document.createElement('span');name.className='name';name.textContent=photo.name;button.append(image,name);button.addEventListener('click',()=>{if(design==='fan'&&selected!==i){setSelection(i);return;}opener=button;dialog.showModal();showFull(i);});if(design==='index'){button.addEventListener('mouseenter',()=>setSelection(i));button.addEventListener('focus',()=>setSelection(i));}wall.append(button);});setSelection(0);wall.scrollLeft=0;wall.classList.remove('is-entering');requestAnimationFrame(()=>wall.classList.add('is-entering'));}
async function showFull(index){const token=++request;viewIndex=Math.max(0,Math.min(photos.length-1,index));const photo=photos[viewIndex];document.querySelector('#viewer-count').textContent=`${viewIndex+1} / ${photos.length}`;document.querySelector('#full-name').textContent=photo.name;const credit=document.querySelector('#credit');credit.textContent=photo.credit;credit.href=photo.page;document.querySelector('#full-prev').disabled=viewIndex===0;document.querySelector('#full-next').disabled=viewIndex===photos.length-1;document.querySelector('#error').hidden=true;try{const image=new Image();image.src=photo.src;image.alt=photo.name+' at Sundance 2026';await image.decode();if(token!==request)return;image.id='full-image';image.className='image-enter';document.querySelector('#full-image').replaceWith(image);}catch{if(token!==request)return;document.querySelector('#full-image').removeAttribute('src');document.querySelector('#full-image').alt='';document.querySelector('#error').hidden=false;document.querySelector('#error').textContent='Photo could not load. Try another photograph.';}}
document.querySelector('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{request++;document.querySelector('#full-image').removeAttribute('src');document.querySelector('#full-image').alt='';opener?.focus();});document.querySelector('#full-prev').addEventListener('click',()=>showFull(viewIndex-1));document.querySelector('#full-next').addEventListener('click',()=>showFull(viewIndex+1));dialog.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();showFull(viewIndex+(event.key==='ArrowRight'?1:-1));}});
let touch;const fullStage=document.querySelector('.full-stage');fullStage.addEventListener('touchstart',event=>{touch={x:event.touches[0].clientX,y:event.touches[0].clientY};},{passive:true});fullStage.addEventListener('touchend',event=>{if(!touch)return;const dx=event.changedTouches[0].clientX-touch.x,dy=event.changedTouches[0].clientY-touch.y;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)showFull(viewIndex+(dx<0?1:-1));touch=null;},{passive:true});fullStage.addEventListener('touchcancel',()=>touch=null,{passive:true});
document.querySelector('#prev').addEventListener('click',()=>move(-1));document.querySelector('#next').addEventListener('click',()=>move(1));wall.addEventListener('scroll',updateScroll,{passive:true});window.addEventListener('resize',updateScroll);document.querySelector('#layout-toggle').addEventListener('click',()=>{const update=()=>{slider=!slider;document.body.classList.toggle('is-slider',slider);document.querySelector('#layout-toggle').textContent=slider?'Grid view':'Slider view';document.querySelector('#layout-toggle').setAttribute('aria-pressed',String(slider));render();};if(document.startViewTransition&&!reduced.matches)document.startViewTransition(update);else update();});
document.querySelectorAll('[data-album]').forEach(button=>button.addEventListener('click',()=>{album=button.dataset.album;history.pushState(null,'','#'+album);render();}));window.addEventListener('popstate',()=>{album=location.hash==='#bts'?'bts':'sundance';if(dialog.open)dialog.close();render();});
async function init(){const [referencesResponse,sourcesResponse]=await Promise.all([fetch('references.json'),fetch('../assets/portraits/sources.json')]);if(!referencesResponse.ok||!sourcesResponse.ok)throw Error('load');const references=await referencesResponse.json(),sources=await sourcesResponse.json();const requested=new URLSearchParams(location.search).get('design');const reference=references.find(item=>item.id===requested)||references[0];design=reference.id;document.body.dataset.design=design;document.title='Run Amok — '+reference.title;document.querySelector('#title').textContent=reference.title;const select=document.querySelector('#design');references.forEach((item,i)=>{const option=document.createElement('option');option.value=item.id;option.textContent=`${String(i+1).padStart(2,'0')} — ${item.title}`;select.append(option);});select.value=design;select.addEventListener('change',()=>{location.href='gallery.html?design='+select.value+(album==='bts'?'#bts':'');});document.querySelector('#reference').href=reference.url;document.querySelector('#reference').title=reference.source;photos=names.map(name=>{const slug=name.toLowerCase().replaceAll(' ','-');return {name,src:`../assets/portraits/${slug}-web.jpg`,...sources.find(source=>source.slug===slug)};});album=location.hash==='#bts'?'bts':'sundance';render();}
init().catch(()=>{status.hidden=false;status.textContent='Photos could not load. Refresh to try again.';});
